command:example.dev:code:
# Exporte e compare com backup anterior
$current = Export-ColorScriptMetadata -Path "./current-metadata.json" -IncludeFileInfo -PassThru
$previous = Get-Content "./previous-metadata.json" | ConvertFrom-Json
$new = $current | Where-Object { $_.Name -notin $previous.Name }
$removed = $previous | Where-Object { $_.Name -notin $current.Name }
Write-Host "Novos scripts: $($new.Count) | Scripts removidos: $($removed.Count)"

dev:remarks.maml:para:
Recupera o diretório de cache resolvido. `Cache.Path` continua sendo a substituição opcional configurada pelo usuário;
`Cache.EffectivePath` mostra o diretório que o módulo realmente usa após os padrões da plataforma e
substituições de ambiente são aplicadas.

command:example.dev:code:
$config = Get-ColorScriptConfiguration
if ($config.Startup.AutoShowOnImport) {
    Write-Host "Os scripts de inicialização estão habilitados"
}

$config = Get-ColorScriptConfiguration
if ($config.Cache.Path) {
    Write-Host "Caminho de cache personalizado configurado: $($config.Cache.Path)"
} else {
    Write-Host "Usando o caminho de cache padrão"
}

Write-Host "Caminho de cache efetivo: $($config.Cache.EffectivePath)"

# Crie cache para scripts filtrados
Get-ColorScriptList -Tag Recommended -AsObject |
    ForEach-Object {
        New-ColorScriptCache -Name $_.Name -PassThru
    } |
    Format-Table Name, Status

# Encontre o primeiro script que corresponda a um padrão para exibição rápida
$script = Get-ColorScriptList -Name "aurora-*" -AsObject | Select-Object -First 1
if ($script) {
    Show-ColorScript -Name $script.Name -PassThru
}

# Verifique se todos os scripts referenciados existem antes de executar a automação
$requiredScripts = @("bars", "arch", "mandelbrot-zoom")
$available = Get-ColorScriptList -AsObject | Select-Object -ExpandProperty Name
$missing = $requiredScripts | Where-Object { $_ -notin $available }
if ($missing) {
    Write-Warning "Scripts ausentes: $($missing -join ', ')"
} else {
    Write-Host "Todos os scripts necessários estão disponíveis"
}

# Crie vários colorscripts para um projeto
$scriptNames = @("company-logo", "team-banner", "status-display")
foreach ($name in $scriptNames) {
    New-ColorScript -Name $name -Category "Corporate" -Tag "Custom" -OutputPath ".\src" | Out-Null
}
Write-Host "$($scriptNames.Count) modelos de colorscript criados"

# Verifique as convenções de nomes de scripts
$validName = "123-start"
$invalidNames = @("-invalid", "_underscore-only", "contains space")
foreach ($name in $invalidNames) {
    try {
        New-ColorScript -Name $name -OutputPath ./temp -WhatIf -ErrorAction Stop
    } catch {
        Write-Warning "Nome inválido '$name': $_"
    }
}

# Crie com validação de categoria e tag
$categories = Get-ColorScriptList -AsObject | Select-Object -ExpandProperty Category -Unique
if ("Retro" -in $categories) {
    New-ColorScript -Name "retro-party" -OutputPath ./ColorScripts-Enhanced/Scripts -Category "Artistic" -Tag "Fun","Social"
} else {
    Write-Warning "Categoria Retro não encontrada"
}

# Verifique se a redefinição foi bem-sucedida
$config = Reset-ColorScriptConfiguration -PassThru
if ($null -eq $config.Cache.Path -and $config.Cache.EffectivePath) {
    Write-Host "Configuração restaurada ao padrão da plataforma"
} else {
    Write-Host "Configuração restaurada, mas usando um caminho personalizado: $($config.Cache.Path)"
}

# Crie uma apresentação de slides de colorscripts geométrico
Get-ColorScriptList -Category Geometric -AsObject |
    ForEach-Object {
        Show-ColorScript -Name $_.Name
        Start-Sleep -Seconds 3
    }

# Exemplo de tratamento de erros
try {
    Show-ColorScript -Name "nonexistent-script" -ErrorAction Stop
} catch {
    Write-Warning "Script não encontrado: $_"
    Show-ColorScript  # Fallback para aleatório
}

# Construir integração de automação
if ($env:CI) {
    Show-ColorScript -Name "Galaxy" -NoCache
} else {
    Show-ColorScript  # Exibição aleatória para uso interativo
}

# Tarefa agendada para saudação do terminal
$scriptPath = "$(Get-Module ColorScripts-Enhanced).ModuleBase\Scripts\mandelbrot-zoom.ps1"
if (Test-Path $scriptPath) {
    & $scriptPath
} else {
    Show-ColorScript -Name mandelbrot-zoom
}
